import { PreChartTriageRows } from "@/components/staff/PreChartTriageRows";
import { SchedulingTile } from "@/components/scheduling/SchedulingTile";
import { WorkspaceSectionOrder } from "@/components/staff/WorkspaceSectionOrder";
import { waitingOnOthers } from "@/components/staff/workspaceOwnership";
import { listMatchReviews } from "@/lib/patientMatching";
import { Fragment, useEffect, useState, type ReactNode } from "react";
import { RescreenActionDetail, RescreenDueTile } from "@/components/clinician/RescreenDueTile";
import { act as runAct, actFor } from "@/lib/actions/act";
import { Link, useHydrated, useNavigate } from "@tanstack/react-router";
import { AlertTriangle, ChevronDown, Clock3, FileText, MoreHorizontal, Pill } from "lucide-react";
import { toast } from "sonner";
import { AdelanteEHR, VISIT_STATUS_LABEL, useEhr, type Appointment, type Patient } from "@/lib/ehr";
import { attentionCaseload, isCareRole, isCoordinatorRole, notifyNeedsClosing, rescreenTileRole, scheduleSegments, workspaceActionRows, workspaceTileOrder, type ActionGroup, type ScheduleSegment, type WorkspaceActionRow, type WorkspaceTileId } from "@/lib/clinicianWorkspace";
import type { WorkspaceActor } from "@/lib/workspaceIdentity";
import { isPrescriberRole, STAFF_ROSTER, useActingStaff } from "@/lib/roles";
import { staffPatientLabel } from "@/lib/staffPatientLabel";
import { roleSeesApptRequest } from "@/components/scheduling/AppointmentRequestsCard";
import { openDashboardAction } from "@/lib/dashboardActionBus";
import { listUnassignedPatients } from "@/lib/coordination";
import { openMentionsFor } from "@/lib/staffThreads";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { StaffVisitActions } from "@/components/scheduling/VisitActions";

const SEGMENT_LABEL: Record<ScheduleSegment, string> = { up_next: "Up next", in_progress: "In progress / checked in", done: "Done today", closed: "Cancelled · Missed visit · late cancel · rescheduled" };
const GROUP_LABEL: Record<ActionGroup, string> = { now: "Now", today: "Today", week: "This week" };
const iconFor = (kind: WorkspaceActionRow["kind"]) => kind === "crisis" || kind === "crisis_note" || kind === "severity" || kind === "escalation" ? AlertTriangle : kind === "refill" ? Pill : kind === "closing" || kind === "unsigned" || kind === "cosign" ? FileText : Clock3;

/**
 * Live rows, counts and summaries read the in-memory store and the clock, which
 * differ between the server render and the browser. The server and the first
 * browser render show the same neutral placeholder; live content mounts after
 * hydration so React never regenerates the tree (and never drops an early click).
 */
export function WorkspaceDashboard(props: Parameters<typeof WorkspaceDashboardLive>[0]) {
  const hydrated = useHydrated();
  if (!hydrated) return <div className="space-y-4" data-testid="workspace-dashboard-loading" aria-busy="true"><p className="text-sm text-muted-foreground">Loading your workspace…</p></div>;
  return <WorkspaceDashboardLive {...props} />;
}

function WorkspaceDashboardLive({ actor, appointments, needsClosing, weekAppointments, patients, launch, openChart, requestsAndBooking }: { actor: WorkspaceActor; appointments: Appointment[]; needsClosing: Appointment[]; weekAppointments: Appointment[]; patients: Patient[]; launch: (id: string) => void; openChart: (patientId: string) => void; requestsAndBooking: ReactNode }) {
  const acting = useActingStaff();
  const actorKey = actor.staffId;
  const storageKey = `adelante:workspace-tiles:${actorKey}`;
  const [openTiles, setOpenTiles] = useState<Record<WorkspaceTileId, boolean>>({ schedule: true, actions: true, caseload: false, requests: false, coordinator: true, scheduling: true });
  const [scheduleSegment, setScheduleSegment] = useState<ScheduleSegment>("up_next");
  const [showWeek, setShowWeek] = useState(false);
  const [focusGroup, setFocusGroup] = useState<ActionGroup | "all">("all");
  const [focusKind, setFocusKind] = useState<WorkspaceActionRow["kind"] | null>(null);
  useEffect(() => { try { const raw = localStorage.getItem(storageKey); if (raw) setOpenTiles((v) => ({ ...v, ...JSON.parse(raw) })); } catch { /* storage optional */ } }, [storageKey]);
  const toggle = (id: WorkspaceTileId, value: boolean) => { setOpenTiles((v) => { const next = { ...v, [id]: value }; try { localStorage.setItem(storageKey, JSON.stringify(next)); } catch { /* storage optional */ } return next; }); };
  useEffect(() => { const openBooking = () => { toggle("requests", true); window.setTimeout(() => document.getElementById("book-session")?.scrollIntoView({ behavior: "smooth", block: "start" }), 50); }; window.addEventListener("adelante:open-booking", openBooking); return () => window.removeEventListener("adelante:open-booking", openBooking); }, [storageKey]);
  useEffect(() => {
    const timer = window.setTimeout(() => notifyNeedsClosing({ ...actor, role: actor.role }, needsClosing), 2000);
    return () => window.clearTimeout(timer);
  }, [actor.staffId, actor.role, needsClosing.map((a) => a.id).join("|")]);
  const segments = scheduleSegments(appointments);
  const rowsJson = useEhr(() => JSON.stringify(workspaceActionRows({ actor: { ...actor, role: actor.role }, needsClosing })));
  const rows = JSON.parse(rowsJson) as WorkspaceActionRow[];
  const caseload = attentionCaseload({ ...actor, role: actor.role }, rows);
  const unsigned = rows.filter((r) => r.kind === "unsigned").length;
  const cosign = rows.filter((r) => r.kind === "cosign").length;
  const crisis = rows.filter((r) => r.kind === "crisis").length;
  const next = segments.up_next[0];
  const nextPatient = patients.find((p) => p.id === next?.patientId);
  const strip = [
    { id: "next", label: "Next visit", value: next ? `${new Date(next.start).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })} · ${nextPatient ? staffPatientLabel({ role: acting.role, staffId: acting.staffId }, nextPatient.id) : "Patient"}` : "None", tile: "schedule" as const, segment: "up_next" as const, zero: !next },
    { id: "left", label: "Visits left today", value: String(segments.up_next.length + segments.in_progress.length), tile: "schedule" as const, segment: "up_next" as const, zero: segments.up_next.length + segments.in_progress.length === 0 },
    { id: "closing", label: "Needs closing", value: String(rows.filter((r) => r.kind === "closing" || r.kind === "crisis_note").length), tile: "actions" as const, zero: !rows.some((r) => r.kind === "closing" || r.kind === "crisis_note"), kind: "closing" as const },
    { id: "unsigned", label: "Unsigned", value: String(unsigned), tile: "actions" as const, zero: unsigned === 0, kind: "unsigned" as const },
    { id: "cosign", label: "Cosign", value: String(cosign), tile: "actions" as const, zero: cosign === 0, kind: "cosign" as const },
    ...(isPrescriberRole(actor.role) ? [{ id: "refills", label: "Refills", value: String(rows.filter((r) => r.kind === "refill").length), tile: "actions" as const, zero: !rows.some((r) => r.kind === "refill"), kind: "refill" as const }] : []),
    { id: "crisis", label: "Crisis · my patients", value: String(crisis), tile: "actions" as const, zero: crisis === 0, kind: "crisis" as const },
    ...(isCareRole(actor.role) ? [{ id: "contacts", label: "Contacts due", value: String(rows.filter((r) => r.kind === "contact").length), tile: "actions" as const, zero: !rows.some((r) => r.kind === "contact"), kind: "contact" as const }] : []),
  ];
  const openFromStrip = (item: typeof strip[number]) => { toggle(item.tile, true); if (item.tile === "schedule" && "segment" in item && item.segment) setScheduleSegment(item.segment); if (item.tile === "actions") { setFocusGroup("all"); setFocusKind("kind" in item ? item.kind ?? null : null); } document.getElementById(`workspace-tile-${item.tile}`)?.scrollIntoView({ behavior: "smooth", block: "start" }); };
  const order = workspaceTileOrder(actor.role);
  const waiting = rows.filter(row => waitingOnOthers(row, actor));
  const needs = rows.filter(row => !waitingOnOthers(row, actor));

  return <div className="space-y-4" data-testid="workspace-dashboard-tiles">
    <div className="flex gap-1 overflow-x-auto border-y bg-card py-2" aria-label="Today" data-testid="today-strip">
      <span className="sticky left-0 flex shrink-0 items-center bg-card px-2 text-xs font-semibold uppercase text-teal">Today</span>
      {strip.map((item) => <Button key={item.id} variant="ghost" className="h-auto shrink-0 flex-col items-start gap-0 rounded px-3 py-1 text-left" onClick={() => openFromStrip(item)}><span className="text-[10px] text-muted-foreground">{item.label}</span><span className="text-sm font-semibold tabular-nums">{item.value}</span></Button>)}
    </div>
    <WorkspaceSectionOrder waitingIds={["workspace-waiting"]} todayIds={["today-strip", "workspace-schedule", "workspace-scheduling"]}>
    {waiting.length > 0 && <div data-testid="workspace-waiting"><ActionTile secondary rows={waiting} focus={focusGroup} setFocus={setFocusGroup} focusKind={focusKind} setFocusKind={setFocusKind} openChart={openChart} actor={acting} /></div>}
    {order.map((id) => {
      if (id === "schedule") return <div key={id} data-testid="workspace-schedule"><WorkspaceTile id={id} open={openTiles[id]} onOpenChange={(v) => toggle(id, v)} title="Schedule" summary={`${segments.up_next.length} upcoming · ${segments.in_progress.length} checked in · ${segments.done.length} done`}><ScheduleTile segments={segments} week={weekAppointments} selected={scheduleSegment} setSelected={setScheduleSegment} showWeek={showWeek} setShowWeek={setShowWeek} patients={patients} launch={launch} openChart={openChart} actor={acting} /></WorkspaceTile></div>;
       if (id === "actions") return <Fragment key={id}><WorkspaceTile id={id} open={openTiles[id]} onOpenChange={(v) => toggle(id, v)} title="Needs my action" summary={`${rows.length} open · ${rows.filter((r) => r.group === "now").length} now`}><ActionTile rows={needs} countRows={rows} focus={focusGroup} setFocus={setFocusGroup} focusKind={focusKind} setFocusKind={setFocusKind} openChart={openChart} actor={acting} /></WorkspaceTile>{rescreenTileRole(actor.role) && <RescreenDueTile actor={{ ...actor, role: actor.role }} openChart={openChart} />}</Fragment>;
      if (id === "caseload") return <WorkspaceTile key={id} id={id} open={openTiles[id]} onOpenChange={(v) => toggle(id, v)} title="My caseload" summary={`${caseload.length} patients · ${caseload.filter((x) => x.reasons.length).length} need attention`}><CaseloadTile rows={caseload} /></WorkspaceTile>;
      if (id === "requests") { const waiting = AdelanteEHR.listOpenAppointmentRequests().filter((r) => roleSeesApptRequest(actor.role, r.patient, r.request)).length; return <WorkspaceTile key={id} id={id} open={openTiles[id]} onOpenChange={(v) => toggle(id, v)} title="Requests & booking" summary={`${waiting} appointment request${waiting === 1 ? "" : "s"} waiting`}>{requestsAndBooking}</WorkspaceTile>; }
      if (id === "scheduling") return <div key={id} data-testid="workspace-scheduling"><WorkspaceTile id={id} open={openTiles[id] ?? true} onOpenChange={(v) => toggle(id, v)} title="Scheduling" summary="Upcoming visits · appointment requests · Book a visit"><SchedulingTile actor={{ staffId: actor.staffId, staffName: actor.staffName, clinicianId: actor.clinicianId, role: actor.role }} /></WorkspaceTile></div>;
      if (id === "coordinator" && isCoordinatorRole(actor.role)) return <WorkspaceTile key={id} id={id} open={openTiles[id]} onOpenChange={(v) => toggle(id, v)} title="Coordinator queue" summary="Void approvals · unassigned patients · crisis · cosign reassignments"><CoordinatorTile actor={acting} /></WorkspaceTile>;
      return null;
    })}
    </WorkspaceSectionOrder>
  </div>;
}

function WorkspaceTile({ id, title, summary, open, onOpenChange, children }: { id: WorkspaceTileId; title: string; summary: string; open: boolean; onOpenChange: (v: boolean) => void; children: ReactNode }) {
  return <Collapsible open={open} onOpenChange={onOpenChange}><Card id={`workspace-tile-${id}`} className="scroll-mt-28 overflow-hidden" data-testid={`workspace-tile-${id}`}><CollapsibleTrigger asChild><Button variant="ghost" className="h-auto w-full justify-between rounded-none p-4 text-left"><span><span className="block font-display text-lg text-navy">{title}</span><span className="block text-xs font-normal text-muted-foreground">{summary}</span></span><ChevronDown className={`h-4 w-4 transition-transform ${open ? "rotate-180" : ""}`} /></Button></CollapsibleTrigger><CollapsibleContent><div className="border-t p-3 sm:p-4">{children}</div></CollapsibleContent></Card></Collapsible>;
}

function ScheduleTile({ segments, week, selected, setSelected, showWeek, setShowWeek, patients, launch, openChart, actor }: { segments: ReturnType<typeof scheduleSegments>; week: Appointment[]; selected: ScheduleSegment; setSelected: (v: ScheduleSegment) => void; showWeek: boolean; setShowWeek: (v: boolean) => void; patients: Patient[]; launch: (id: string) => void; openChart: (id: string) => void; actor: ReturnType<typeof useActingStaff> }) {
  const rows = showWeek ? week : segments[selected];
  return <div className="space-y-3"><div className="flex gap-1 overflow-x-auto" role="tablist" aria-label="Schedule view">{(Object.keys(SEGMENT_LABEL) as ScheduleSegment[]).map((id) => <Button key={id} role="tab" aria-selected={!showWeek && selected === id} size="sm" variant={!showWeek && selected === id ? "default" : "outline"} className="h-auto shrink-0 py-1.5" onClick={() => { setShowWeek(false); setSelected(id); }}>{SEGMENT_LABEL[id]} <Badge variant="secondary" className="ml-1">{segments[id].length}</Badge></Button>)}<Button role="tab" aria-selected={showWeek} size="sm" variant={showWeek ? "default" : "outline"} className="shrink-0" onClick={() => setShowWeek(!showWeek)}>This week · {week.length}</Button></div>{rows.length === 0 ? <p className="py-4 text-sm text-muted-foreground">Nothing in this view.</p> : <div className="divide-y">{rows.map((a) => <ScheduleRow key={a.id} a={a} patient={patients.find((p) => p.id === a.patientId)} launch={launch} openChart={openChart} actor={actor} />)}</div>}</div>;
}
function ScheduleRow({ a, patient, launch, openChart, actor }: { a: Appointment; patient?: Patient; launch: (id: string) => void; openChart: (id: string) => void; actor: ReturnType<typeof useActingStaff> }) {
  const [editVisit, setEditVisit] = useState(false);
  const now = Date.now(); const sameDay = new Date(a.start).toDateString() === new Date().toDateString(); const hasNote = patient?.progressNotes?.some((n) => n.appointmentId === a.id);
  const primary = a.status === "checked_in" ? { label: "Mark attended", run: () => actFor("visit_attended", "markAppointmentAttended", a.patientId, a.id, { id: actor.staffId, name: actor.staffName, role: actor.role }) } : a.status === "attended" && !hasNote ? { label: "Write note", run: () => patient && openDashboardAction("progress_note", patient.id) } : a.status === "scheduled" && sameDay ? { label: "Check in", run: () => actFor("visit_check_in", "checkInAppointment", a.patientId, a.id, { id: actor.staffId, name: actor.staffName, role: actor.role }) } : undefined;
  const run = () => { try { primary?.run(); if (primary?.label === "Check in") toast.success("Checked in"); if (primary?.label === "Mark attended") toast.success("Marked attended"); } catch (e) { toast.error((e as Error).message); } };
   return <div className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 py-3" data-testid="schedule-row"><time className="w-16 text-sm font-medium tabular-nums">{new Date(a.start).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}</time><div className="min-w-0"><Button variant="link" className="h-auto p-0 text-left text-sm font-medium" onClick={() => patient && openChart(patient.id)}>{patient ? staffPatientLabel({ role: actor.role, staffId: actor.staffId }, patient.id) : "Patient"}</Button><p className="truncate text-xs text-muted-foreground">{AdelanteEHR.getServiceType(a.serviceType)?.label ?? a.serviceType} · <Badge className="h-5 border-0" variant="secondary">{VISIT_STATUS_LABEL[a.status]}</Badge></p></div><div className="flex items-center gap-1">{primary && <Button size="sm" onClick={run}>{primary.label}</Button>}<DropdownMenu><DropdownMenuTrigger asChild><Button size="icon" variant="ghost" aria-label="More visit actions"><MoreHorizontal className="h-4 w-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end">{patient && <><DropdownMenuItem asChild><Link to="/agentic/chart-review/$patientId" params={{ patientId: patient.id }}>Pre-visit review</Link></DropdownMenuItem><DropdownMenuItem asChild><Link to="/agentic/scribe/$patientId" params={{ patientId: patient.id }} search={{ appt: a.id }}>Start AI scribe</Link></DropdownMenuItem><DropdownMenuItem onSelect={() => openDashboardAction("progress_note", patient.id)}>Write note</DropdownMenuItem></>}{a.status === "checked_in" && <DropdownMenuItem onSelect={() => launch(a.id)}>Join session</DropdownMenuItem>}{a.status === "scheduled" && <DropdownMenuItem onSelect={() => setEditVisit(true)}>Reschedule / cancel</DropdownMenuItem>}{a.status === "scheduled" && +new Date(a.start) < now && <DropdownMenuItem onSelect={() => { try { actFor("visit_no_show", "markAppointmentNoShow", a.patientId, a.id, { id: actor.staffId, name: actor.staffName, role: actor.role }); } catch (e) { toast.error((e as Error).message); } }}>Mark Missed visit</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu></div><Dialog open={editVisit} onOpenChange={setEditVisit}><DialogContent><DialogHeader><DialogTitle>Visit actions · {patient ? staffPatientLabel({ role: actor.role, staffId: actor.staffId }, patient.id) : "Patient"}</DialogTitle></DialogHeader><StaffVisitActions appt={a} /></DialogContent></Dialog></div>;
}

function ActionTile({ rows, focus, setFocus, focusKind, setFocusKind, openChart, actor, secondary, countRows }: { secondary?: boolean; countRows?: WorkspaceActionRow[]; rows: WorkspaceActionRow[]; focus: ActionGroup | "all"; setFocus: (v: ActionGroup | "all") => void; focusKind: WorkspaceActionRow["kind"] | null; setFocusKind: (v: WorkspaceActionRow["kind"] | null) => void; openChart: (id: string) => void; actor: ReturnType<typeof useActingStaff> }) {
  const navigate = useNavigate();
  const [handoff, setHandoff] = useState<WorkspaceActionRow | null>(null);
  // "closing" also shows crisis notes — the strip count includes them.
  const visible = focusKind ? rows.filter((r) => r.kind === focusKind || (focusKind === "closing" && r.kind === "crisis_note")) : rows;
  const all = countRows ?? rows;
  const countVisible = focusKind ? all.filter((r) => r.kind === focusKind || (focusKind === "closing" && r.kind === "crisis_note")) : all;
  const grouped = { now: visible.filter((r) => r.group === "now"), today: visible.filter((r) => r.group === "today"), week: visible.filter((r) => r.group === "week") };
  const act = (r: WorkspaceActionRow) => { try { if (r.kind === "closing") { const a = AdelanteEHR.listAppointments().find((x) => `closing:${x.id}` === r.id); if (a?.status === "attended") return openDashboardAction("progress_note", r.patientId); if (a) actFor("visit_attended", "markAppointmentAttended", a.patientId, a.id, { id: actor.staffId, name: actor.staffName, role: actor.role }); } else if (r.kind === "crisis") { if (r.action === "Reassign") setHandoff(r); else navigate({ to: "/escalations", search: { view: undefined, type: "crisis", owner: undefined, overdue: undefined } }); } else if (r.kind === "author_out") navigate({ to: "/team-calendar" }); else if (r.kind === "reschedule" && r.sourceId) { runAct("calendar_reschedule_done", "markRescheduleHandled", { role: actor.role, staffId: actor.staffId }, { itemId: r.sourceId }); toast.success("Marked handled"); } else if (r.kind === "continuity") navigate({ to: "/record/$patientId", params: { patientId: r.patientId } }); else if (r.kind === "coverage") navigate({ to: "/coverage-release" }); else if (r.kind === "reassign_needed") navigate({ to: "/admin-staff" }); else if (r.kind === "restricted_open") navigate({ to: "/quality-compliance" }); else if (r.kind === "county_reminder") navigate({ to: "/county-reporting" }); else if (r.kind === "content_waiting" || r.kind === "content_review" || r.kind === "content_gap") navigate({ to: "/admin-content" }); else if (r.kind === "escalation") navigate({ to: "/escalations", search: { view: "mine", type: undefined, owner: undefined, overdue: undefined } }); else if (r.kind === "reply" && r.sourceId) { const m = openMentionsFor(actor.staffId).find((x) => x.id === r.sourceId); if (m) navigate({ to: "/team-messages", search: { thread: m.threadId } }); } else if (r.kind === "crisis_note") navigate({ to: "/record/$patientId", params: { patientId: r.patientId }, search: { section: "notes" } }); else if (r.kind === "unsigned") r.sourceId ? navigate({ to: "/record/$patientId", params: { patientId: r.patientId }, search: { section: "notes" } }) : openDashboardAction("progress_note", r.patientId); else if (r.kind === "refill") openDashboardAction("refill_decision", r.patientId); else if (r.kind === "screener" && r.sourceId && r.action === "Send re-screen") runAct("rescreen_send", "sendRescreenTask", r.patientId, r.sourceId); else if (r.kind === "contact") openDashboardAction("dashboard_contact", r.patientId); else if (r.kind === "chase" && r.sourceId) { if (r.action === "Claim") { runAct("referral_chase_claim", "claimChaseTask", { role: actor.role, staffId: actor.staffId, name: actor.staffName }, r.sourceId); toast.success("Follow-up is now yours"); } else navigate({ to: "/referral-queue" }); } else if (r.kind === "match") navigate({ to: "/data-exchange" }); else if (r.kind === "severity") navigate({ to: "/record/$patientId", params: { patientId: r.patientId }, search: { section: "tracking" } }); else if (r.kind === "task") navigate({ to: "/record/$patientId", params: { patientId: r.patientId }, search: { section: "tasks" } }); else openChart(r.patientId); } catch (e) { toast.error((e as Error).message); } };
   return <div className="space-y-4">{!secondary && <PreChartTriageRows actor={actor} />}{!secondary && <><Link to="/escalations" search={{ view: undefined, type: undefined, owner: undefined, overdue: undefined }} className="text-xs text-teal underline" data-testid="needs-action-escalations-link">See all escalations to</Link><div className="flex gap-1 overflow-x-auto" role="group" aria-label="Action due group">{focusKind && <Button size="sm" variant="outline" onClick={() => setFocusKind(null)}>{focusKind} ×</Button>}<Button size="sm" variant={focus === "all" ? "default" : "outline"} onClick={() => setFocus("all")}>All · {countVisible.length}</Button>{(["now", "today", "week"] as ActionGroup[]).map((g) => <Button key={g} size="sm" variant={focus === g ? "default" : "outline"} onClick={() => setFocus(g)}>{GROUP_LABEL[g]} · {countVisible.filter((r) => r.group === g).length}</Button>)}</div></>}{(["now", "today", "week"] as ActionGroup[]).filter((g) => focus === "all" || focus === g).map((g) => <section key={g}><h3 className="mb-1 text-xs font-semibold uppercase text-teal">{GROUP_LABEL[g]} · {grouped[g].length}</h3>{grouped[g].length === 0 ? <p className="py-2 text-xs text-muted-foreground">No items.</p> : <div className="divide-y">{grouped[g].map((r) => { const Icon = iconFor(r.kind); return <div key={r.id} className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 py-2.5" data-testid={`action-row-${r.kind}`}><Icon className={`h-4 w-4 ${r.kind === "crisis" ? "text-destructive" : "text-teal"}`} /><div className="min-w-0"><p className="truncate text-sm font-medium">{r.patientName}</p><p className="truncate text-xs text-muted-foreground">{r.kind === "crisis_note" && <Badge variant="destructive" className="mr-1 h-4 px-1 text-[10px]" title="Draft — pending clinical sign-off. Crisis notes: 1 calendar day.">Crisis note</Badge>}{r.label} · {r.due}</p>{r.kind === "screener" && r.sourceId && <RescreenActionDetail patientId={r.patientId} screenerKey={r.sourceId} viewer={actor} />}</div><div className="flex items-center gap-1"><Button size="sm" variant={r.kind === "crisis" ? "destructive" : "outline"} onClick={() => act(r)}>{r.action}</Button>{r.kind === "crisis" && r.action === "Open crisis" && <Button size="sm" variant="ghost" onClick={() => setHandoff(r)}>Hand off</Button>}{r.kind === "closing" && r.action === "Mark attended" && <DropdownMenu><DropdownMenuTrigger asChild><Button size="icon" variant="ghost" aria-label="Other closing actions"><MoreHorizontal className="h-4 w-4" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={() => { try { actFor("visit_no_show", "markAppointmentNoShow", r.patientId, r.id.slice("closing:".length), { id: actor.staffId, name: actor.staffName, role: actor.role }); } catch (e) { toast.error((e as Error).message); } }}>Mark Missed visit</DropdownMenuItem></DropdownMenuContent></DropdownMenu>}</div></div>; })}</div>}</section>)}<CrisisHandoffDialog row={handoff} onClose={() => setHandoff(null)} actor={actor} /></div>;
}

/** §Batch C4 — hand off / reassign a crisis to a named person with a reason (audited via runAction). */
function CrisisHandoffDialog({ row, onClose, actor }: { row: WorkspaceActionRow | null; onClose: () => void; actor: ReturnType<typeof useActingStaff> }) {
  const [to, setTo] = useState("");
  const [reason, setReason] = useState("");
  const people = STAFF_ROSTER.filter((m) => m.active !== false && m.id !== actor.staffId && !["billing", "credentialing_coordinator", "sys_admin"].includes(m.role));
  const save = () => {
    if (!row?.sourceId) return;
    try {
      runAct("crisis_handoff", "handOffCrisisEscalation", row.patientId, row.sourceId, { toStaffId: to, reason, byStaffId: actor.staffId, byName: actor.staffName, byRole: actor.role });
      toast.success("Crisis handed off");
      setTo(""); setReason(""); onClose();
    } catch (e) { toast.error((e as Error).message); }
  };
  return <Dialog open={!!row} onOpenChange={(o) => !o && onClose()}><DialogContent><DialogHeader><DialogTitle>{row?.action === "Reassign" ? "Reassign crisis" : "Hand off crisis"} · {row?.patientName}</DialogTitle></DialogHeader><div className="space-y-3"><label className="block text-sm">New owner<select aria-label="New owner" className="mt-1 w-full rounded-md border bg-background p-2 text-sm" value={to} onChange={(e) => setTo(e.target.value)}><option value="">Choose a person</option>{people.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label className="block text-sm">Reason<textarea aria-label="Handoff reason" className="mt-1 w-full rounded-md border bg-background p-2 text-sm" rows={2} value={reason} onChange={(e) => setReason(e.target.value)} /></label><Button onClick={save} disabled={!to || reason.trim().length < 3}>Hand off</Button></div></DialogContent></Dialog>;
}

function CaseloadTile({ rows }: { rows: ReturnType<typeof attentionCaseload> }) { const caseloadActor = useActingStaff(); return <div className="divide-y">{rows.map(({ patient, reasons }) => <div key={patient.id} className="flex items-center justify-between gap-3 py-2"><div className="min-w-0"><p className="truncate text-sm font-medium">{staffPatientLabel({ role: caseloadActor.role, staffId: caseloadActor.staffId }, patient.id)}</p><div className="mt-1 flex flex-wrap gap-1">{reasons.slice(0, 3).map((r) => <Badge key={r.id} variant={r.kind === "crisis" ? "destructive" : "secondary"}>{r.label}</Badge>)}{reasons.length === 0 && <span className="text-xs text-muted-foreground">No open attention items</span>}</div></div><Button asChild size="sm" variant="outline"><Link to="/record/$patientId" params={{ patientId: patient.id }} search={{}}>Open chart</Link></Button></div>)}</div>; }
function CoordinatorTile({ actor }: { actor: ReturnType<typeof useActingStaff> }) { const voids = useEhr(() => AdelanteEHR.listPendingNoteVoids({ staffId: actor.staffId, clinicianId: actor.clinicianId, name: actor.staffName, role: actor.role })); const unassigned = useEhr(() => listUnassignedPatients()); const crisis = useEhr(() => AdelanteEHR.listOpenCrisisEscalations()); const cosigns = useEhr(() => AdelanteEHR.listNotesAwaitingCosign()); const matches = useEhr(() => listMatchReviews("open")); const items = [{ label: "Patient matching", count: matches.length, to: "/data-exchange" as const }, { label: "Void approvals", count: voids.length, to: "/inbox" as const }, { label: "Unassigned patients", count: unassigned.length, to: "/admin-coordination" as const }, { label: "Crisis", count: crisis.length, to: "/escalations" as const }, { label: "Cosign reassignments", count: cosigns.length, to: "/cosign-inbox" as const }]; return <div className="grid gap-2 sm:grid-cols-2">{items.map((i) => <Button key={i.label} asChild variant="outline" className="h-auto justify-between p-3"><Link to={i.to}><span>{i.label}</span><Badge>{i.count}</Badge></Link></Button>)}</div>; }

