  "in_progress",
  "completed",
  "missed",
  "cancelled",
];

export function TaskWorkRow({
  task,
  canWrite = true,
  patientSlot,
  className,
  tablePresentation = false,
  draftCache,
}: {
  task: CaseTask;
  canWrite?: boolean;
  /** Optional patient link/label — the caseload card shows it, the record doesn't. */
  patientSlot?: ReactNode;
  className?: string;
  tablePresentation?: boolean;
  draftCache?: TaskWorkDraftCache;
}) {
  const { role, staffName, staffId } = useActingStaff();
  const draftKey = `${staffId}:${role}:${task.id}`;
  const [open, setOpen] = useTaskDraftField(draftCache, draftKey, "open", false);
  const [due, setDue] = useTaskDraftField(draftCache, draftKey, "due", task.dueDate.slice(0, 10));
  const [priority, setPriority] = useTaskDraftField(draftCache, draftKey, "priority", taskPriority(task));
  const [note, setNote] = useTaskDraftField(draftCache, draftKey, "note", "");
  const [followUp, setFollowUp] = useTaskDraftField(draftCache, draftKey, "followUp", null);
  const [followUpDue, setFollowUpDue] = useTaskDraftField(draftCache, draftKey, "followUpDue", new Date().toISOString().slice(0, 10));

  const isEngagement = task.sourceAutomationId === "engagement_risk_automation" && task.source === "engagement_risk_automation" && task.title === ENGAGEMENT_TASK_TITLE;
  const status = worklistStatusFor(task);
  const today = new Date().toISOString().slice(0, 10);
  const overdue =
    status !== "completed" && status !== "cancelled" && task.dueDate.slice(0, 10) < today;

  function saveField(patch: Parameters<typeof AdelanteEHR.updateCaseTaskFields>[1], label: string) {
    if (AdelanteEHR.updateCaseTaskFields(task.id, patch, staffName, role)) {
      toast.success(`${label} updated.`, { description: `Recorded as ${staffName}.` });
    }
  }

  return (
    <li
      className={cn(
        tablePresentation ? "text-sm min-w-0" : "rounded-lg border p-3 text-sm",
        !tablePresentation && overdue && "border-input bg-surface-sunk",
        className,
      )}
      data-testid="task-work-row"
    >
      <div className={tablePresentation ? "flex flex-wrap items-start justify-between gap-3" : "flex items-start justify-between gap-3"}>
        <Button variant="ghost"
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          className={tablePresentation ? "flex min-w-0 w-full items-start gap-2 text-left h-auto px-0" : "flex min-w-0 flex-1 items-start gap-2 text-left h-auto px-0"}
        >
          {open ? (
            <ChevronDown className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
          ) : (
            <ChevronRight className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
          )}
          <span className="min-w-0">
            <span className="flex flex-wrap items-center gap-2">
              <span className="font-medium text-navy">{task.title}</span>
              <Badge className={cn("text-[10px] capitalize", PRIORITY_TONE[taskPriority(task)])}>
                {taskPriority(task)}
              </Badge>
              <StatusChip lang="en" state={status === "completed" ? "done" : status === "cancelled" ? "closed" : task.status === "snoozed" ? "upnext" : task.claimedBy ? (task.claimedBy === staffName ? "yourturn" : "team") : task.assignedTo === staffName || task.assignedTo === role ? "yourturn" : "team"} label={STATUS_LABEL[status]} />
            </span>
            {task.detail && !task.dedupeKey?.startsWith("screener-item9-unanswered:") && (
              <span className="mt-0.5 block text-xs text-muted-foreground">{task.detail}</span>
            )}
            <span className="mt-1 flex flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
              <span className="inline-flex items-center gap-1">
                <Clock className="h-3 w-3" /> Due {task.dueDate.slice(0, 10)}
              </span>
              <span className="capitalize">{task.origin.replace(/_/g, " ")}</span>
              {task.claimedBy && <span>Claimed by {task.claimedBy}</span>}
            </span>
          </span>
        </Button>
        <div className="shrink-0 text-right">{patientSlot}</div>
        {isEngagement && <EngagementTaskClose task={task} canWrite={canWrite} />}
        {tablePresentation && <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" size="icon" aria-label={`More: ${task.id}`}><MoreHorizontal /></Button></DropdownMenuTrigger><DropdownMenuContent><DropdownMenuItem onSelect={() => setOpen(true)}>Task details</DropdownMenuItem></DropdownMenuContent></DropdownMenu>}
      </div>

      {open && (
        <div className="mt-3 space-y-3 border-t pt-3">
          <div className="grid gap-1 text-[11px] text-muted-foreground sm:grid-cols-2">
            <div>Assigned to {task.assignedTo}</div>
            {task.taskType && <div>Type: {task.taskType}</div>}
            <div>
              Created <ClientDate value={task.createdAt} />
            </div>
            {task.lastEditedBy && (
              <div>
                Last edited by {task.lastEditedBy} · <ClientDate value={task.lastEditedAt!} />
              </div>
            )}
          </div>
          {task.dedupeKey?.startsWith("screener-item9-unanswered:") && ["therapist", "pmhnp", "physician", "clinical_coordinator"].includes(role) && <p className="text-sm">{task.detail}</p>}
          <AutoCreatedFromNote task={task} />

          {canWrite && !isEngagement && (
            <>
              <div className="grid gap-2 sm:grid-cols-3">
                <div className="space-y-1">
                  <Label className="text-[10px] text-muted-foreground">Status</Label>
                  <Select
                    value={status}
                    onValueChange={(v) => {
                      if (AdelanteEHR.setWorklistStatus(task.id, v as WorklistStatus, staffName, role))
                        toast.success(`Status set to ${STATUS_LABEL[v as WorklistStatus]}.`, {
                          description: `Recorded as ${staffName}.`,
                        });
                    }}
                  >
                    <SelectTrigger className="h-9 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {STATUS_CHOICES.map((s) => (
                        <SelectItem key={s} value={s} className="text-xs">
                          {STATUS_LABEL[s]}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1">
                  <Label className="text-[10px] text-muted-foreground">Due date</Label>
                  <Input
                    type="date"
                    value={due}
                    className="h-9 text-xs"
                    onChange={(e) => setDue(e.target.value)}
                    onBlur={() => due && due !== task.dueDate.slice(0, 10) && saveField({ dueDate: due }, "Due date")}
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-[10px] text-muted-foreground">Priority</Label>
                  <Select
                    value={priority}
                    onValueChange={(v) => {
                      setPriority(v as TaskPriority);
                      saveField({ priority: v as TaskPriority }, "Priority");
                    }}
                  >
                    <SelectTrigger className="h-9 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {(["routine", "urgent", "stat"] as TaskPriority[]).map((p) => (
                        <SelectItem key={p} value={p} className="text-xs capitalize">
                          {p}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="space-y-1">
                <Label className="text-[10px] text-muted-foreground">Add a note</Label>
                <Textarea
                  rows={2}
                  value={note}
                  placeholder="What happened on this task?"
                  onChange={(e) => setNote(e.target.value)}
                />
                <div className="flex flex-wrap gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-9 text-xs"
                    onClick={() => {
                      if (!AdelanteEHR.addCaseTaskNote(task.id, note, staffName, role)) {
                        toast.error("Write a note first.");
                        return;
                      }
                      setNote("");
                      toast.success("Note added.", { description: `Recorded as ${staffName}.` });
                    }}
                  >
                    Save note
                  </Button>
                  {status !== "completed" && (
                    <Button
                      size="sm"
                      className="h-9 text-xs"
                      onClick={() => setFollowUp(`Follow-up: ${task.title}`)}
                    >
                      Complete and schedule follow-up
                    </Button>
                  )}
                </div>
              </div>

              {followUp !== null && (
                <div className="space-y-2 rounded-lg border bg-secondary/40 p-2.5">
                  <Label className="text-[10px] text-muted-foreground">Next step</Label>
                  <Input
                    value={followUp}
                    className="h-9 text-xs"
                    onChange={(e) => setFollowUp(e.target.value)}
                  />
                  <div className="flex flex-wrap items-center gap-2">
                    <Input
                      type="date"
                      value={followUpDue}
                      className="h-9 w-[160px] text-xs"
                      onChange={(e) => setFollowUpDue(e.target.value)}
                    />
                    <Button
                      size="sm"
                      className="h-9 text-xs"
                      onClick={() => {
                        if (!followUp.trim()) {
                          toast.error("Give the next step a title.");
                          return;
                        }
                        act("task", "createCaseTask", {
                          patientId: task.patientId,
                          assignedTo: task.assignedTo,
                          title: followUp.trim(),
                          dueDate: followUpDue,
                          origin: "manual",
                          priority: taskPriority(task),
                        });
                        AdelanteEHR.setWorklistStatus(task.id, "completed", staffName, role);
                        AdelanteEHR.addCaseTaskNote(
                          task.id,
                          `Completed; next step scheduled: ${followUp.trim()} (due ${followUpDue}).`,
                          staffName,
                          role,
                        );
                        setFollowUp(null);
                        toast.success("Task completed and next step created.", {
                          description: `Recorded as ${staffName}.`,
                        });
                      }}
                    >
                      Create
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      className="h-9 text-xs"
                      onClick={() => setFollowUp(null)}
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}

          {(task.notes?.length ?? 0) > 0 && (
            <ul className="space-y-1.5">
              {task.notes!.map((n) => (
                <li key={n.id} className="rounded border bg-card p-2 text-xs">
                  <div className="text-foreground">{n.text}</div>
                  <div className="mt-0.5 text-[10px] text-muted-foreground">
                    {n.authorName} · {n.authorRole.replace(/_/g, " ")} · <ClientDate value={n.at} />
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </li>
  );
}

